Here is the commit message:
accel/amdxdna: Fix out-of-bounds memset in command slot
 handling

The remaining space in a command slot may be smaller than the size of
the command header. Clearing the command header with memset() before
verifying the available slot space can result in an out-of-bounds write
and memory corruption.

Fix this by moving the memset() call after the size validation.

Fixes: 3d32eb7a5ecf ("accel/amdxdna: Fix cu_idx being cleared by memset() during command setup")
Reviewed-by: Mario Limonciello (AMD) <superm1@kernel.org>
Signed-off-by: Lizhi Hou <lizhi.hou@amd.com>
Link: https://patch.msgid.link/20260217185415.1781908-1-lizhi.hou@amd.com

Here is the root cause:
The memset to clear the command header was performed before validating that the remaining slot space is sufficient to hold the header and payload, causing an out-of-bounds write when the slot is too small.

Here is the patch:

 static int
 aie2_cmdlist_fill_npu_cf(struct amdxdna_gem_obj *cmd_bo, void *slot, size_t *size)
 {
 	struct cmd_chain_slot_npu *npu_slot = slot;
 	u32 cmd_len;
 	void *cmd;

-	memset(npu_slot, 0, sizeof(*npu_slot));
 	cmd = amdxdna_cmd_get_payload(cmd_bo, &cmd_len);
 	if (*size < sizeof(*npu_slot) + cmd_len)
 		return -EINVAL;

+	memset(npu_slot, 0, sizeof(*npu_slot));
 	npu_slot->cu_idx = amdxdna_cmd_get_cu_idx(cmd_bo);
 	if (npu_slot->cu_idx == INVALID_CU_IDX)
 		return -EINVAL;

 	npu_slot->type = EXEC_NPU_TYPE_NON_ELF;
 	npu_slot->arg_cnt = cmd_len / sizeof(u32);
 	memcpy(npu_slot->args, cmd, cmd_len);

 	*size = sizeof(*npu_slot) + cmd_len;
 	return 0;
 }

 static int
 aie2_cmdlist_fill_npu_dpu(struct amdxdna_gem_obj *cmd_bo, void *slot, size_t *size)
 {
 	struct cmd_chain_slot_npu *npu_slot = slot;
 	struct amdxdna_cmd_start_npu *sn;
 	u32 cmd_len;
 	u32 arg_sz;

-	memset(npu_slot, 0, sizeof(*npu_slot));
 	sn = amdxdna_cmd_get_payload(cmd_bo, &cmd_len);
 	arg_sz = cmd_len - sizeof(*sn);
 	if (cmd_len < sizeof(*sn) || arg_sz > MAX_NPU_ARGS_SIZE)
 		return -EINVAL;

 	if (*size < sizeof(*npu_slot) + arg_sz)
 		return -EINVAL;

+	memset(npu_slot, 0, sizeof(*npu_slot));
 	npu_slot->cu_idx = amdxdna_cmd_get_cu_idx(cmd_bo);
 	if (npu_slot->cu_idx == INVALID_CU_IDX)
 		return -EINVAL;

 	npu_slot->type = EXEC_NPU_TYPE_PARTIAL_ELF;
 	npu_slot->inst_buf_addr = sn->buffer;
 	npu_slot->inst_size = sn->buffer_size;
 	npu_slot->inst_prop_cnt = sn->prop_count;
 	npu_slot->arg_cnt = arg_sz / sizeof(u32);
 	memcpy(npu_slot->args, sn->prop_args, arg_sz);

 	*size = sizeof(*npu_slot) + arg_sz;
 	return 0;
 }

